class Solution { public:vector<int> minEdgeReversals(int n,vector<vector<int>>& edges){vector<vector<pair<int,int>>> graph(n);for(auto& edge:edges){graph[edge[0]].push_back({edge[1],0});graph[edge[1]].push_back({edge[0],1});}vector<int> parent(n,-1),edgeCost(n),order;parent[0]=0;int total=0;queue<int> pending;pending.push(0);while(!pending.empty()){int node=pending.front();pending.pop();order.push_back(node);for(auto [next,cost]:graph[node])if(parent[next]==-1){parent[next]=node;edgeCost[next]=cost;total+=cost;pending.push(next);}}vector<int> answer(n);answer[0]=total;for(int index=1;index<n;++index){int node=order[index];answer[node]=answer[parent[node]]+(edgeCost[node]==0?1:-1);}return answer;} };
